#include <iostream>
struct B {
    virtual char name() const {
        return 'B';
    }
    virtual ~B() = default;
};
struct D : B {
    char name() const override {
        return 'D';
    }
};
void preserve() {
    try {
        throw D{};
    } catch (const B &) {
        throw;
    }
}
void slice() {
    try {
        throw D{};
    } catch (const B &e) {
        throw e;
    }
}
int main() {
    try {
        preserve();
    } catch (const B &e) {
        std::cout << e.name() << " ";
    }
    try {
        slice();
    } catch (const B &e) {
        std::cout << e.name();
    }
}

